import{_ as t,o as s,c as o,a3 as r}from"./chunks/framework.Ki30n65y.js";const n="/depgate/screenshots/access-users.png",a="/depgate/screenshots/user-add.png",i="/depgate/screenshots/access-service-accounts.png",d="/depgate/screenshots/service-account-add.png",w=JSON.parse('{"title":"Access","description":"","frontmatter":{},"headers":[],"relativePath":"admin/users.md","filePath":"admin/users.md"}'),h={name:"admin/users.md"};function g(l,e,c,p,u,m){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h1><p>Security users manage who can use DepGate under <strong>Access</strong> in the sidebar. It has three tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>For</th></tr></thead><tbody><tr><td><strong>Users</strong></td><td>People, their role and status. This page.</td></tr><tr><td><strong>Single sign-on</strong></td><td>Which email domains may sign in with your identity provider, and the providers themselves. See <a href="./sso">Single sign-on</a>.</td></tr><tr><td><strong>Service accounts</strong></td><td>Credentials CI systems use to get download tokens. See <a href="#service-accounts">Service accounts</a>.</td></tr></tbody></table><p><img src="'+n+'" alt="The Users tab"></p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>For</th><th>Can</th></tr></thead><tbody><tr><td><strong>User</strong></td><td>Developers and anyone who installs packages</td><td>Copy registry settings, check packages, and request waivers. Lands on the <strong>Registry</strong> page after signing in.</td></tr><tr><td><strong>Security</strong></td><td>The team that runs DepGate</td><td>Everything a User can, plus manage policies, exceptions, malware entries, repositories, people, single sign-on, email, webhooks, log streaming, the artifact cache and jobs. Lands on the <strong>Dashboard</strong>.</td></tr><tr><td><strong>Service account</strong></td><td>CI/CD systems</td><td>Mint CI download tokens through the API. A token lasts at most 1 day. Cannot sign in or change anything.</td></tr></tbody></table><p>The first Security account is created from <code>ADMIN_EMAIL</code> and <code>ADMIN_PASSWORD</code> when DepGate starts for the first time.</p><p>People sign in with a password, or with your company identity provider when <a href="./sso">single sign-on</a> is set up. Either way, <strong>the role comes from the Users tab</strong>: single sign-on proves who someone is, never what they may do.</p><h2 id="add-a-person" tabindex="-1">Add a person <a class="header-anchor" href="#add-a-person" aria-label="Permalink to &quot;Add a person&quot;">​</a></h2><ol><li>Choose <strong>Add user</strong>.</li><li>Enter the person&#39;s <strong>Email</strong> and choose the <strong>Role</strong>: <strong>User</strong> or <strong>Security</strong>.</li><li>Keep <strong>Send a password invitation</strong> selected and choose <strong>Send invitation</strong>. With single sign-on on, the box starts cleared: people who sign in through the identity provider need no password, so choose <strong>Add user</strong> instead.</li></ol><p><img src="'+a+'" alt="Adding a user"></p><p>DepGate emails the person a link to choose their own password. You never see or set it. The link works once and expires after 7 days. Until the person signs in, the list marks them <strong>Invited</strong> (or <strong>Not signed in yet</strong> when no invitation was sent); choose <strong>⋮ → Resend invitation</strong> to send it again.</p><div class="tip custom-block"><p class="custom-block-title">Without email</p><p>If email is not set up, or sending fails, DepGate shows you the invitation link after you add the person. Send it to them yourself, through a channel you trust. Set up <a href="./email">Email</a> so invitations and password resets are sent automatically.</p></div><h2 id="the-list" tabindex="-1">The list <a class="header-anchor" href="#the-list" aria-label="Permalink to &quot;The list&quot;">​</a></h2><p>Search by any part of an email, and filter by <strong>Type</strong> (<strong>Local</strong> or <strong>SSO</strong>), <strong>Role</strong> and <strong>Status</strong>. Long lists are split into pages: choose <strong>Rows per page</strong> (10, 20, 50 or 100; your browser remembers the choice for each list), a page number, or type one into <strong>Go to page</strong>. Every list in DepGate pages the same way.</p><table tabindex="0"><thead><tr><th>Column</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Email</strong></td><td>The sign-in identity. <strong>SSO</strong> marks someone single sign-on added on their first sign-in.</td></tr><tr><td><strong>Role</strong></td><td>User or Security.</td></tr><tr><td><strong>Sign-in</strong></td><td>When and how they last signed in, and every method they have used (Password, or an identity provider&#39;s name).</td></tr><tr><td><strong>Status</strong></td><td><strong>Active</strong>, <strong>Invited</strong> / <strong>Not signed in yet</strong>, or <strong>Disabled</strong>.</td></tr></tbody></table><h2 id="change-a-role" tabindex="-1">Change a role <a class="header-anchor" href="#change-a-role" aria-label="Permalink to &quot;Change a role&quot;">​</a></h2><p>Choose <strong>⋮ → Make Security</strong> or <strong>Make User</strong>. The person is signed out everywhere and gets the new role at their next sign-in, by any method. You cannot change your own role, or demote the last Security user who can sign in.</p><h2 id="disable-a-person" tabindex="-1">Disable a person <a class="header-anchor" href="#disable-a-person" aria-label="Permalink to &quot;Disable a person&quot;">​</a></h2><p>Choose <strong>⋮ → Disable</strong>. A disabled person cannot sign in with a password or single sign-on, and their browser sessions and registry tokens stop working at once. <strong>Enable</strong> lets them back in.</p><p>Disable people who leave, rather than deleting them: while unlisted people may sign in with single sign-on, a deleted person who can still sign in at the identity provider is added back as User.</p><h2 id="sign-out-everywhere" tabindex="-1">Sign out everywhere <a class="header-anchor" href="#sign-out-everywhere" aria-label="Permalink to &quot;Sign out everywhere&quot;">​</a></h2><p>Choose <strong>⋮ → Sign out everywhere</strong> to end every browser session and registry token of a person, for example after a laptop is lost. They can sign in again straight away.</p><h2 id="send-a-password-reset" tabindex="-1">Send a password reset <a class="header-anchor" href="#send-a-password-reset" aria-label="Permalink to &quot;Send a password reset&quot;">​</a></h2><p>Choose <strong>⋮ → Send password reset</strong> to email a person a link to choose a new password. Their current password keeps working until they use the link; then they are signed out everywhere.</p><h2 id="remove-a-person" tabindex="-1">Remove a person <a class="header-anchor" href="#remove-a-person" aria-label="Permalink to &quot;Remove a person&quot;">​</a></h2><p>Choose <strong>⋮ → Delete</strong>. You cannot delete your own account, or the last Security account.</p><h2 id="passwords" tabindex="-1">Passwords <a class="header-anchor" href="#passwords" aria-label="Permalink to &quot;Passwords&quot;">​</a></h2><ul><li>People change their own password, or use <strong>Forgot password?</strong> on the sign-in page. The reset link is emailed, works once, and expires after 60 minutes.</li><li>Resetting a password ends every session that was signed in with the old one, browser and registry token alike.</li><li>Ten wrong passwords for one email within 15 minutes, or a hundred from one address, make sign-in wait 15 minutes. Successful sign-ins never count.</li></ul><h2 id="service-accounts" tabindex="-1">Service accounts <a class="header-anchor" href="#service-accounts" aria-label="Permalink to &quot;Service accounts&quot;">​</a></h2><p>A service account lets a CI/CD system obtain download tokens without using a person&#39;s account.</p><p><img src="'+i+'" alt="The Service accounts tab"></p><ol><li>On the <strong>Service accounts</strong> tab, choose <strong>Add service account</strong>.</li><li>Enter a <strong>Name</strong>, such as <code>github-actions</code> or <code>jenkins-prod</code>, and choose <strong>Create</strong>.</li><li>Copy the key. <strong>It is shown only once.</strong></li><li>Store the key as a secret in your CI system.</li></ol><p><img src="'+d+'" alt="Creating a service account"></p><p>Pipelines exchange the key for a CI token at the start of each job. The token lasts at most 1 day. See <a href="/depgate/developers/ci-pipelines">CI/CD pipelines</a>. The list shows when each service account was last used. Delete a service account to revoke its key.</p><h2 id="registry-tokens" tabindex="-1">Registry tokens <a class="header-anchor" href="#registry-tokens" aria-label="Permalink to &quot;Registry tokens&quot;">​</a></h2><p>Each person&#39;s Registry page shows a snippet with their personal <strong>registry token</strong>, separate from their browser session. Every download made with it is recorded in their name. The token lifetime (30 days by default) is set under <strong>Settings → Repositories → Gateway security</strong>.</p><p>Every change on this page is recorded in the <a href="./audit-log">Audit Log</a>.</p>',38)])])}const b=t(h,[["render",g]]);export{w as __pageData,b as default};
